#include "DspAlignment.h"
#include "TestSupport.h"
int main(){AlignmentProposal p;PathLatency first[]={{4,true,true,2048}};CHECK(calculateAlignment(first,p));CHECK((p.delay==std::array<uint64_t,3>{2048,2048,0}));PathLatency second[]={{3,true,true,3072},{4,true,true,2048},{3,false,false,999999}};CHECK(calculateAlignment(second,p));CHECK((p.delay==std::array<uint64_t,3>{0,0,1024}));PathLatency third[]={{1,true,true,2500},{2,true,true,3000},{4,true,true,2048}};CHECK(calculateAlignment(third,p));CHECK((p.delay==std::array<uint64_t,3>{500,0,952}));PathLatency max[]={{4,true,true,65536}};CHECK(calculateAlignment(max,p));max[0].samples=65537;CHECK(!calculateAlignment(max,p));max[0].samples=2048;max[0].valid=false;CHECK(!calculateAlignment(max,p));PathLatency overflow[]={{1,true,true,0xffffffffULL},{1,true,true,1}};CHECK(!calculateAlignment(overflow,p));std::cout<<"PASS per-path latency sums, asymmetric compensation, inactive exclusion, invalid/overflow/max rejection\n";}
